<?php require '../includes/functions.php';$pageTitle='Create an account';$errors=[];if(post()){verify_csrf();$username=textval('username');$email=strtolower(textval('email'));$password=textval('password');$errors=password_errors($password);if(!preg_match('/^[A-Za-z0-9_]{3,40}$/',$username))$errors[]='Username must be 3–40 letters, numbers or underscores.';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>190)$errors[]='Enter a valid email address.';if($password!==textval('confirm_password'))$errors[]='Passwords do not match.';if(!$errors){try{query('INSERT INTO users(username,email,password) VALUES (?,?,?)',[$username,$email,password_hash($password,PASSWORD_BCRYPT)]);flash('Account created. Please sign in.');redirect('auth/login.php');}catch(PDOException $e){if($e->getCode()!=='23000')throw $e;$errors[]='That username or email is already registered.';}}}require '../includes/header.php';?><section class="container section"><div class="auth-panel panel"><span class="eyebrow">YOUR FRAGRANCE JOURNEY</span><h1>Create an account</h1><?php errors($errors);?><form method="post" data-validate><?php csrf();?><label>Username<input name="username" pattern="[A-Za-z0-9_]{3,40}" minlength="3" maxlength="40" autocomplete="username" required value="<?=e(textval('username'))?>"></label><label>Email address<input name="email" type="email" autocomplete="email" maxlength="190" required value="<?=e(textval('email'))?>"></label><label>Password<input name="password" type="password" minlength="10" maxlength="72" autocomplete="new-password" required></label><p class="muted small">Use 10–72 bytes. Avoid reusing a password from another account.</p><label>Confirm password<input name="confirm_password" type="password" minlength="10" maxlength="72" autocomplete="new-password" required></label><button class="full">Create account</button></form><p>Already registered? <a href="<?=e(url('auth/login.php'))?>">Sign in</a></p></div></section><?php require '../includes/footer.php';?>
